SELECT 'fr', 'entreprise-keepnew', 'Entreprise Keepnew', 'page', 'draft', '[{"type":"hero","bg":"cream","layout":"1-1","visual_type":"photo","eyebrow":"QUI SOMMES-NOUS ?","h1":"Une équipe unique pour vous servir !","body":"Notre objectif est simple : rendre vos pièces de vie plus saines. Canapés, matelas, voitures, terrasses : nous venons chez vous avec le même souci du travail bien fait.","cta_eyebrow":"DEVIS & RENDEZ-VOUS","cta_title":"Nous contacter","cta_url":"#contact","pills":[{"icon":"star","text":"4,9/5 · +159 avis","style":"white"},{"icon":"heart","text":"Entreprise familiale liégeoise","style":"rose"},{"icon":"home","text":"À domicile & en atelier","style":"night"}],"visible":["desktop","tablet","mobile"]},{"type":"seo-content","bg":"white","h2":"Notre objectif est simple : rendre vos pièces de vie plus saines.","body":"<p><strong>Mathieu Forêt</strong>, le plus jeune des frères, a lancé Keepnew pendant ses études d\'e-business. Il constatait un manque d\'offres digitales pour le nettoyage de véhicules à domicile et a fondé l\'entreprise sous le statut d\'étudiant entrepreneur, avec l\'ambition de grandir vite.</p><p><strong>Antoine Forêt</strong>, son grand frère, l\'a rejoint à la fin de ses études. Fort de plus de 10 ans d\'expérience en marketing digital, il s\'est donné pour mission de développer l\'entreprise, de professionnaliser les services et de renforcer sa présence en ligne.</p><p>Récemment, <strong>Thibault Decker</strong> est devenu le troisième associé. Son rôle : répondre à une demande qui grandit et élargir l\'offre de services.</p>","visible":["desktop","tablet","mobile"]},{"type":"how","bg":"alt","columns":"3","eyebrow":"L\'ÉQUIPE","h2":"Les personnes derrière Keepnew","steps":[{"num":"MF","title":"Mathieu Forêt — Fondateur","body":"A créé l\'entreprise pendant ses études. Il cherche en permanence à améliorer les services proposés."},{"num":"AF","title":"Antoine Forêt — Co-fondateur","body":"Se concentre sur le développement de l\'entreprise, la satisfaction des clients et l\'efficacité de leur expérience."},{"num":"TD","title":"Thibault Decker — Associé, responsable service","body":"Veut améliorer les process de nettoyage et les services. Il surveille les nouvelles opportunités de services et place la satisfaction client en priorité."}],"visible":["desktop","tablet","mobile"]},{"type":"prestation","bg":"white","eyebrow":"NOS VALEURS","h2":"Ce qui guide notre travail au quotidien","intro":"Derrière chaque intervention, les mêmes engagements.","columns":"2","items":[{"title":"La satisfaction du client","desc":"Votre avis compte : vous payez uniquement après la prestation, une fois le résultat validé."},{"title":"Le professionnalisme du service","desc":"Des techniciens formés, du matériel professionnel et des produits adaptés à chaque matière."},{"title":"L\'amélioration continue","desc":"Nous perfectionnons sans cesse nos process et explorons de nouveaux services."},{"title":"Une présence digitale","desc":"Réservation en ligne, devis clairs et suivi simple : tout se fait en quelques minutes."}],"visible":["desktop","tablet","mobile"]},{"type":"how","bg":"cream","columns":"3","eyebrow":"KEEPNEW EN BREF","h2":"Une entreprise de terrain, appréciée de ses clients","steps":[{"num":"4,9/5","title":"Note Google","body":"Une note moyenne construite intervention après intervention."},{"num":"+159","title":"Avis clients","body":"Des clients satisfaits en province de Liège, à Namur et au Luxembourg."},{"num":"Visé","title":"Notre atelier","body":"Un atelier dédié au polissage et au traitement céramique des véhicules."}],"visible":["desktop","tablet","mobile"]},{"type":"seo-content","bg":"white","h2":"Une entreprise familiale liégeoise reconnue","body":"<p>Keepnew a été sélectionné parmi les 10 finalistes du Trophée de l\'Indépendant 2024 organisé par Orange, sur plus de 850 candidatures : <a href=\\"/blog/trophee-independant-orange-2024\\">lire l\'article</a>. La même année, nous avons ouvert <a href=\\"/blog/nouvel-atelier-keepnew-a-vise\\">notre atelier à Visé</a>, dédié aux véhicules.</p>","visible":["desktop","tablet","mobile"]},{"type":"seo-content","bg":"rose","h2":"Sommes-nous déjà venus près de chez toi ?","body":"<p>Non ? Qu\'attends-tu pour prendre rendez-vous alors ?</p>","cta_label":"Prenez RDV en ligne","cta_style":"primary","cta_align":"left","visible":["desktop","tablet","mobile"]},{"type":"text","bg":"white","html":"<h3>Fixons un RDV ensemble dès aujourd\'hui !</h3><p><strong>Vous payez après le nettoyage</strong>, par carte, par QR code, en espèces, ou sur facture pour les professionnels.</p><p><strong>Plusieurs services à réserver ?</strong> Contactez-nous par téléphone au <a href=\\"tel:+32455138419\\">+32 (0)4 55 13 84 19</a> ou via le formulaire ci-dessous.</p>","visible":["desktop","tablet","mobile"]},{"type":"contact","bg":"cream","eyebrow":"CONTACT","h2":"Parlons de votre projet","intro":"Une question, plusieurs services à réserver, un devis sur mesure ? Écrivez-nous, nous vous répondons personnellement.","subjects":"Plusieurs services à réserver\\nDevis sur mesure\\nUne question","visible":["desktop","tablet","mobile"]},{"type":"reviews","bg":"white","eyebrow":"ILS NOUS FONT CONFIANCE","h2":"Ce que disent nos clients","visible":["desktop","tablet","mobile"]},{"type":"cta-final","bg":"blue","eyebrow":"RÉSERVATION EN LIGNE","title":"Prêt à nous <span class=\\"hl-inverse\\">confier votre intérieur</span> ?","cta_title":"Prenez RDV en ligne","phone":"+32 (0)4 55 13 84 19","visible":["desktop","tablet","mobile"]}]', 'À propos de Keepnew : une équipe unique pour vous servir', 'Découvrez Keepnew, entreprise familiale liégeoise de nettoyage à domicile : l\'histoire de Mathieu, Antoine et Thibault, nos valeurs et nos engagements.', 'index,follow', 0
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM kn_pages WHERE slug = 'entreprise-keepnew' AND lang = 'fr');
